55	/* P180：自动亮度平滑引擎（每次拿到新 lux 调用）。
56	 * 夜览开启时让步（夜览压暗是用户主动意图）；未在自动状态只更新 g_auto_cur
57	 * 基准不写背光（关闭后下次开启从当前亮度平滑起步）。 */
58	static void dm_auto_bright_tick(int lux)
59	{
60	    if (!g_auto_bright)
61	    {
62	        g_auto_cur = -1;
63	        return;
64	    }
65	    if (dm_night_shift_enabled())
66	        return;                       /* 夜览优先：不干扰背光 */
67	
68	    int target = dm_auto_bright_target(lux);
69	    if (g_auto_cur < 0)
70	        g_auto_cur = g_screen_brightness;   /* 起步：从手动基准平滑过渡 */
71	    int diff = target - g_auto_cur;
72	    /* 每秒限幅 ±3% 平滑渐变（防环境光跳变闪背光） */
73	    if (diff > 0)
74	        g_auto_cur += diff < 3 ? diff : 3;
75	    else if (diff < 0)
76	        g_auto_cur += diff > -3 ? diff : -3;
77	    if (g_auto_cur != g_screen_brightness || diff != 0)
78	    {
79	        if (g_auto_cur < 0)  g_auto_cur = 0;
80	        if (g_auto_cur > 100) g_auto_cur = 100;
81	        dm_brightness_write(g_auto_cur);
82	    }
83	}
