94	/****************************************************************************
95	 * 内部：暗光状态机 tick（每次拿到新 lux 调用一次）
96	 ****************************************************************************/
97	static void dm_als_dark_tick(int lux, uint32_t now_ms)
98	{
99	    static uint32_t s_debounce_start = 0;   /* 进入暗光候选的起始时刻 */
100	    static uint32_t s_last_trigger  = 0;    /* 上次弹窗时刻（冷却） */
101	
102	    /* P157 确认门已移除（2026-09-04）：传感器清洁后能正常读数，
103	     * 无需等待 ≥200 lux 才启用暗光检测。仅保留开机稳定期保险。 */
104	
105	    /* P156：开机稳定期内不触发暗光弹窗——驱动首个有效 ALS 转换前
106	     * 可能持续推 0（CH0 未就绪），开机即弹"知道了"是误报 */
107	    if (now_ms - s_start_ms < DM_ALS_STARTUP_MS)
108	        return;
109	
110	    bool dark_now = (lux >= 0) && (lux < DM_ALS_DARK_LUX);
111	
112	    if (dark_now) {
113	        if (!s_dark_active) {
114	            /* 刚进入暗光：记录候选起点，等 debounce 确认 */
115	            if (s_debounce_start == 0)
116	                s_debounce_start = now_ms;
117	            if (now_ms - s_debounce_start >= DM_ALS_DARK_DEBOUNCE_MS) {
118	                /* 防抖通过：确认暗光 */
119	                s_dark_active = true;
120	                s_debounce_start = 0;
121	                /* 冷却检查：距上次触发 ≥ 冷却期才再次提醒 */
122	                if (s_last_trigger == 0 ||
123	                    now_ms - s_last_trigger >= DM_ALS_DARK_COOLDOWN_MS) {
124	                    s_last_trigger = now_ms;
125	                    syslog(LOG_INFO, "[als] dark_tick TRIGGER lux=%d cb=%s\n",
126	                           lux, s_dark_cb ? "set" : "NULL");
127	                    if (s_dark_cb)
128	                        s_dark_cb();
129	                }
130	            }
131	        }
132	        /* 已确认暗光：保持，不重复触发（冷却已含） */
133	    }
134	    else {
135	        /* 光线恢复：重置状态机 */
136	        s_dark_active = false;
137	        s_debounce_start = 0;
138	    }
139	}
